INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me302', 'stk-moh_ammed', 'ME 302', 'doc', '{"docs": [{"id": "stk-dr-f118643", "n": "Dr. Fadi Al-Bedoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 302 - Term 231\n\nالتحضير: ياحذه ببداية المحاضرة وإذا تأخرت شوي (تقريبا 5 دقايق) يسجلك متأخر.\n\nالشرح: شرحه كويس في أغلب التشباتر بس أحيانا تحسه يمر بسرعة على بعض الأفكار عشان يخلص لأن المنهج أساسا دسم. شخصيا كنت أعتمد شرحه عشان آخذ الكونسبت.\n\nالكويزات: بعد كل واجب تسلمونه يكون فيه كويز، والكويزات مستواها متوسط (إذا حليت الواجب وفهمته إن شاء الله إنك جاهز للكويز وتقدر تفلله). فيه نقطة لازم تنتبه لها…أحيانا يجي الدكتور ويعطيكم الكويز بدون مايقول لكم قبلها إني بعطيكم كويز في اليوم الفلاني، بحجة إنه قال لكم من قبل إن بعد كل واجب بعطيكم كويز، فأنت لازم تكون جاهز إنك تاخذ الكويز في أي يوم بعد تسليم الواجب.\n\nالتصحيح: حقاني ودقيق في بعض الأشياء.\n\nإضافات:\n- الدكتور تحسه أحيانا غير متساعد أو مرن في بعض الأمور (هو أخلاقه حلوة بس في العمل جاد وشديد).\n- الدكتور مايعجبه إنك تسحب على الكلاس بأنك تمسك الجوال أو تسرح ويمكن يقعد يسألك.\n\nالقريد النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537190-me302", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fadi-al-bedoor/118643/20", "user": "Moh_ammed", "ts": 1704259929000, "tid": 118643, "pn": 20}}]}', 1704259929000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
